alter table public.conversations alter column created_by set default auth.uid(); revoke update on public.conversations from public,anon,authenticated; create policy conversation_members_creator_guard on public.conversation_members as restrictive for insert to authenticated with check(exists(select 1 from public.conversations c where c.id=conversation_id and c.created_by=(select auth.uid())) and (user_id=(select auth.uid()) or public.hayna_can_dm((select auth.uid()),user_id))); create policy conversation_members_participant_guard on public.conversation_members as restrictive for select to authenticated using(public.hayna_is_conversation_member(conversation_id,(select auth.uid()))); revoke all on public.conversation_members from public,anon;
